DT_INST_FOREACH_STATUS_OKAY(MAX17048_DEFINE)

#ifdef CONFIG_EMUL_MAX17048

#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c_emul.h>

/* Emulator data and functions */
static struct max17048_emul_data {
	uint16_t version;
	uint16_t soc;
	uint16_t vcell;
	int16_t crate;
} emul_data = {
	.version = 0x0010, /* Expected version */
	.soc = 0x4000,     /* 25% (0x4000 / 256 = 25) */
	.vcell = 0x1000,   /* Some voltage (raw ADC value) */
	.crate = 0x4000,   /* Some crate value (raw value) */
};

static int max17048_emul_read_reg(const struct emul *target, uint8_t reg_addr, uint16_t *val)
{
	switch (reg_addr) {
	case REGISTER_VERSION:
		*val = emul_data.version;
		break;
	case REGISTER_SOC:
		*val = emul_data.soc;
		break;
	case REGISTER_VCELL:
		*val = emul_data.vcell;
		break;
	case REGISTER_CRATE:
		*val = emul_data.crate;
		break;
	default:
		LOG_ERR("Emul: Attempt to read unsupported register 0x%02x", reg_addr);
		return -EIO;
	}
	return 0;
}

static int max17048_emul_transfer_fct(const struct emul *target, struct i2c_msg *msgs,
				       int num_msgs, int bytes_to_read)
{
	if (num_msgs == 0) {
		return 0;
	}

	/* Write message */
	if ((msgs[0].flags & I2C_MSG_RW_MASK) == I2C_MSG_WRITE) {
		if (msgs[0].len == 1) { /* Register address write */
			uint8_t reg_addr = msgs[0].buf[0];

			if (num_msgs == 2 && (msgs[1].flags & I2C_MSG_RW_MASK) == I2C_MSG_READ) {
				/* Write register address, then read data */
				uint16_t val;
				int rc = max17048_emul_read_reg(target, reg_addr, &val);
				if (rc) {
					return rc;
				}
				if (msgs[1].len != 2) {
					LOG_ERR("Emul: Expected 2 bytes read, got %d", msgs[1].len);
					return -EIO;
				}
				sys_put_be16(val, msgs[1].buf);
				return 0;
			}
		}
	}

	LOG_ERR("Emul: Unsupported I2C transfer type (num_msgs: %d, flags: 0x%x, len: %d)",
		num_msgs, msgs[0].flags, msgs[0].len);
	return -EIO;
}

static int max17048_emul_init(const struct emul *target, const struct device *parent)
{
	return 0;
}

/* Public API for the emulator */
void emul_max17048_set_crate_status(int value)
{
	emul_data.crate = value;
}

static const struct i2c_emul_api max17048_emul_api = {
	.transfer = max17048_emul_transfer_fct,
};

#define MAX17048_EMUL_DEFINE(n)                                                                    \
	static struct i2c_emul_data max17048_emul_data_##n;                                        \
	EMUL_DT_INST_DEFINE(n, max17048_emul_init, &max17048_emul_data_##n,                        \
			    &max17048_emul_api, NULL);

DT_INST_FOREACH_STATUS_OKAY(MAX17048_EMUL_DEFINE)

#endif /* CONFIG_EMUL_MAX17048 */
